// D-218 (2026-09-23): one FAILED card per workflow per hour. CH-S01 runs every 5 minutes, so a single
// broken node used to post twelve cards an hour. Static data persists between production executions.
const state = $getWorkflowStaticData('global');
state.lastSent = state.lastSent || {};
const now = Date.now();
const out = [];
for (const item of $input.all()) {
  const wf = (item.json.workflow && (item.json.workflow.id || item.json.workflow.name)) || 'unknown';
  if (state.lastSent[wf] && now - state.lastSent[wf] < 3600000) continue;
  state.lastSent[wf] = now;
  out.push(item);
}
return out;
